sqlite3 -readonly stars.db -header -column "SELECT o.x, o.y, s.zone, o.subtype, o.orbit, o.size, o.name, sqrt( (o.x-k.ox)*(o.x-k.ox)+(o.y-k.oy)*(o.y-k.oy)) as dist FROM orbitals o JOIN stars s ON s.id = o.star_id JOIN (SELECT x AS ox, y AS oy FROM orbitals WHERE name='Confidence') k WHERE o.subtype in ('p11', 'p12', 'p33', 'p35') and o.orbit in (2, 3, 4, 5) and dist <= 200 ORDER BY o.size, s.zone, dist, o.name;"
